#include "plan/cozo/plan-cozo.h"
#include <cassert>
#include <filesystem>
int main() { namespace fs=std::filesystem; auto dir=fs::temp_directory_path()/"llama-plan-cozo-test"; std::error_code ec; fs::remove_all(dir,ec); fs::create_directories(dir,ec); std::string error; { common_plan_cozo_store store; assert(store.open((dir/"plan.db").string(),error)); common_plan_state plan; plan.id="p"; plan.scope=common_plan_scope::global; plan.purpose="persist and resume"; plan.goal="persist"; assert(store.create(plan,error)); auto op=common_plan_operation{}; op.kind=common_plan_operation_kind::add_step; op.plan_id="p"; op.expected_version=0; op.reason_summary="test"; op.step=common_plan_step{"s","step","objective"}; op.step->intended_contribution="preserve the persisted evidence"; op.step->selected_tool="web_search"; op.step->tool_call=common_plan_tool_call{"web_search",R"({"query":"cozo"})"}; assert(store.apply(op,plan,error)); } { common_plan_cozo_store store; assert(store.open((dir/"plan.db").string(),error)); auto plan=store.get("p",error); assert(plan && plan->scope==common_plan_scope::global && plan->purpose=="persist and resume" && plan->steps.size()==1 && plan->steps[0].intended_contribution=="preserve the persisted evidence" && plan->steps[0].tool_call && plan->steps[0].tool_call->name=="web_search" && plan->version==1); auto events=store.history("p",error); assert(events.size()==1); assert(store.erase("p",error)); } fs::remove_all(dir,ec); return 0; }
